const std=@import("std");
fn solve(a:[]const i64,out:*[10]i64)usize{if(a.len<=1){if(a.len==1)out[0]=a[0];return a.len;}const pivot=a[0];var best:[10]i64=undefined;var bl:usize=0;var i:usize=1;while(i<a.len):(i+=1){if(a[i]<pivot){var tail:[10]i64=undefined;var m:usize=0;for(i+1..a.len)|j|{if(a[j]>=a[i]){tail[m]=a[j];m+=1;}}var co:[10]i64=undefined;const sl=solve(tail[0..m],&co);var cand:[10]i64=undefined;cand[0]=a[i];@memcpy(cand[1..sl+1],co[0..sl]);if(sl+1>bl){bl=sl+1;best[0]=cand[0];i=1;while(i<bl):(i+=1){best[i]=cand[i];}}}}var tail:[10]i64=undefined;var m:usize=0;for(1..a.len)|i|{if(a[i]>=pivot){tail[m]=a[i];m+=1;}}var co:[10]i64=undefined;const sl=solve(tail[0..m],&co);var cand:[10]i64=undefined;cand[0]=pivot;@memcpy(cand[1..sl+1],co[0..sl]);if(sl+1>bl){bl=sl+1;@memcpy(best[0..bl],cand[0..bl]);}@memcpy(out[0..bl],best[0..bl]);return bl;}
export fn longest_subsequence(v:[*]const i64,n:usize)callconv(.c)i64{if(n<2 or n>11)return -1;const k=v[0];if(k<1 or k>10 or n!=@as(usize,@intCast(k+1)))return -1;var a:[10]i64=undefined;for(0..@intCast(k))|i|{a[i]=v[i+1];if(a[i] < -10 or a[i]>10)return -1;}var out:[10]i64=undefined;const len=solve(a[0..@intCast(k)],&out);var r:i64=@intCast(len);for(0..len)|i|{r=r*21+out[i]+10;}return r;}
